{
  const designVals = Component.prototype.renderVals
  const appVals = function (v) {
    const S = this.state,
      msg = S.apiErr || v.err || null
    const FIELD = {
      'Enter your full name.': 'name',
      'Enter a valid work email.': 'email',
      'Enter your company name.': 'company',
      'Choose your role.': 'role',
      'Choose your monthly volume.': 'volume',
      'Choose the category that matters most.': 'category',
      'Pick at least one thing you\u2019re looking for.': 'goals',
      'Please accept the Terms to continue.': 'agree',
    }
    const bad = msg && FIELD[msg]
    const desc = {},
      inv = {}
    for (const k of ['name', 'email', 'company', 'role', 'volume', 'category', 'goals', 'agree']) {
      desc[k] = bad === k ? 'wl-err' : undefined
      inv[k] = bad === k
    }
    const press = (e) => e.key === ' ' || e.key === 'Enter'
    // Radios: arrows move and select (roving tabindex); goals: arrows only move focus.
    const keys = (n, i, pick, select) => (e) => {
      if (press(e)) {
        e.preventDefault()
        pick()
        return
      }
      const d =
        e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? -1 : 0
      if (!d) return
      e.preventDefault()
      const next = e.currentTarget.parentElement.children[(i + d + n) % n]
      if (next) {
        next.focus()
        if (select) next.click()
      }
    }
    const radios = (items, cur) => {
      const si = items.findIndex((o) => (o.kind ?? o.label) === cur)
      return items.map((o, i) => ({
        ...o,
        role: 'radio',
        checked: i === si,
        tab: (si < 0 ? i === 0 : i === si) ? 0 : -1,
        key: keys(items.length, i, o.pick, true),
      }))
    }
    const reduce = typeof window !== 'undefined' && !!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches
    return {
      hasErr: !!msg,
      err: msg,
      anim: reduce ? { op: v.anim.op, tf: 'none' } : v.anim,
      roles: radios(v.roles, S.role),
      volumes: radios(v.volumes, S.volume),
      cats: radios(v.cats, S.category),
      goals: v.goals.map((o, i) => ({
        ...o,
        role: 'button',
        pressed: S.goals.includes(o.label),
        tab: 0,
        key: keys(v.goals.length, i, o.pick, false),
      })),
      appHpVal: S.hp || '',
      appHp: (e) => this.setState({ hp: e.target.value }),
      appA11y: {
        progress: 'Step ' + (S.step + 1) + ' of 3',
        stepNum: S.step + 1,
        desc,
        inv,
        agree: !!S.agree,
        busy: !!S.busy,
        agreeKey: (e) => {
          if (press(e)) {
            e.preventDefault()
            this.setState((s) => ({ agree: !s.agree }))
          }
        },
        btnKey: (e) => {
          if (press(e)) {
            e.preventDefault()
            e.currentTarget.click()
          }
        },
      },
    }
  }
  Component.prototype.renderVals = function () {
    const v = designVals.call(this)
    return { ...v, ...appVals.call(this, v) }
  }
}

